  // ================== 🎯 weightHistory 工具函数（与学员端一致） ==================
  formatDateKey: function(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  },
  // 取某天的体重：当天没记录就沿用之前最近一次（carry-forward），完全没有则返回 null
  getWeightAt: function(history, dateStr) {
    var w = null;
    for (var i = 0; i < history.length; i++) {
      if (history[i].date <= dateStr) { w = history[i].weight; } else { break; }
    }
    return w;
  },

  fetchAllCloudData: function() {
    if (!this.data.isCoachAuthorized) return;
    wx.showLoading({ title: '加载云端引擎...' });
    this.fetchPendingApplicants();
    this.fetchClientsFromCloud();
    this.fetchSchedulesFromCloud();
    this.fetchActionItems();
  },

  getCoachIdentityNames: function(includeTags) {
    var profile = this.data.coachProfile || {};
    var values = [profile.name, profile.nickname];
    if (includeTags) values = values.concat(profile.coachTags || []);
    var seen = {};
    var names = [];
    for (var i = 0; i < values.length; i++) {
      var name = String(values[i] || '').trim();
      if (name && !seen[name]) {
        seen[name] = true;
        names.push(name);
      }
    }
    return names;
  },

  isRecordOwnedByCurrentCoach: function(record, includeTags) {
    record = record || {};
    if (record.coachOpenid) return record.coachOpenid === this.data.currentCoachOpenid;
    if (record.coachId) return record.coachId === this.data.coachProfile._id;
    return this.getCoachIdentityNames(includeTags).indexOf(record.coach) > -1;
  },

  buildCoachScopeCondition: function(base, includeTags) {
    var _ = wx.cloud.database().command;
    var clauses = [];
    var that = this;
    var append = function(scope) {
      var item = {};
      var key;
      for (key in base) item[key] = base[key];
      for (key in scope) item[key] = scope[key];
      clauses.push(item);
    };
    if (this.data.currentCoachOpenid) append({ coachOpenid: this.data.currentCoachOpenid });
    if (this.data.coachProfile._id) append({ coachId: this.data.coachProfile._id });
    var names = that.getCoachIdentityNames(includeTags);
    for (var i = 0; i < names.length; i++) append({ coach: names[i] });
    if (clauses.length === 0) append({ coachOpenid: '__unauthorized__' });
    return clauses.length === 1 ? clauses[0] : _.or(clauses);
  },

  fetchPendingApplicants: function() {
    var that = this;
    var db = wx.cloud.database();
    var condition = this.buildCoachScopeCondition({ status: 'pending' }, false);
    db.collection('clients').where(condition).get({
      success: function(res) {
        var rawList = res.data || [];
        var list = [];
        for (var i = 0; i < rawList.length; i++) {
          if (!that.isRecordOwnedByCurrentCoach(rawList[i], false)) continue;
          rawList[i].displayName = that.getClientDisplayName(rawList[i]);
          list.push(rawList[i]);
        }
        list.sort(function(a, b) { return (b.appliedAt || 0) - (a.appliedAt || 0); });
        that.setData({ pendingApplicants: list, pendingCount: list.length });
      },
      fail: function(err) {
        console.error('拉取待审核申请失败：', err);
        that.setData({ pendingApplicants: [], pendingCount: 0 });
      }
    });
  },

