  // ================= 🔔 站内信：半屏弹窗（历史记录 + 发送） =================
  sendClientMessage: function(e) {
    var clientId = e.currentTarget.dataset.id;
    var clientName = e.currentTarget.dataset.name;
    var recipients = [];
    var selectedIds = [];
    var activeClient = null;
    for (var i = 0; i < this.data.clientList.length; i++) {
      var client = this.data.clientList[i];
      var displayName = this.getClientDisplayName(client);
      var checked = client._id === clientId || (!clientId && client.name === clientName);
      if (checked) {
        selectedIds.push(client._id);
        activeClient = client;
      }
      recipients.push({
        _id: client._id,
        name: client.name,
        displayName: displayName,
        openid: client.openid || '',
        checked: checked
      });
    }
    this.setData({
      isMsgModalVisible: true,
      msgClientName: activeClient ? activeClient.name : clientName,
      msgClientDisplayName: activeClient ? this.getClientDisplayName(activeClient) : this.getClientDisplayNameByName(clientName),
      msgClientOpenid: activeClient ? (activeClient.openid || '') : '',
      msgHistory: [],
      msgInput: '',
      msgScrollInto: '',
      messageRecipientList: recipients,
      selectedMessageClientIds: selectedIds,
      allMessageClientsSelected: recipients.length > 0 && selectedIds.length === recipients.length
    });
    this.fetchMsgHistory();
  },

  closeMsgModal: function() {
    this.setData({
      isMsgModalVisible: false,
      messageRecipientList: [],
      selectedMessageClientIds: [],
      allMessageClientsSelected: false
    });
  },

  onMessageRecipientsChange: function(e) {
    var selectedIds = e.detail.value || [];
    var selectedMap = {};
    for (var i = 0; i < selectedIds.length; i++) selectedMap[selectedIds[i]] = true;
    var recipients = this.data.messageRecipientList.slice();
    for (var j = 0; j < recipients.length; j++) recipients[j].checked = !!selectedMap[recipients[j]._id];
    this.setData({
      messageRecipientList: recipients,
      selectedMessageClientIds: selectedIds,
      allMessageClientsSelected: recipients.length > 0 && selectedIds.length === recipients.length
    });
  },

  toggleAllMessageRecipients: function() {
    var shouldSelectAll = !this.data.allMessageClientsSelected;
    var recipients = this.data.messageRecipientList.slice();
    var selectedIds = [];
    for (var i = 0; i < recipients.length; i++) {
      recipients[i].checked = shouldSelectAll;
      if (shouldSelectAll) selectedIds.push(recipients[i]._id);
    }
    this.setData({
      messageRecipientList: recipients,
      selectedMessageClientIds: selectedIds,
      allMessageClientsSelected: shouldSelectAll
    });
  },

  // 拉取发给当前学员的历史消息（最近 20 条，最新的排最下面）
  fetchMsgHistory: function() {
    var that = this;
    wx.showNavigationBarLoading();
    // 客户端 get 单次最多 20 条：按时间倒序取最近 20 条，再反转成「旧在上、新在下」
    var db = wx.cloud.database();
    var condition = this.data.msgClientOpenid
      ? db.command.or([{ targetOpenid: this.data.msgClientOpenid }, { clientName: this.data.msgClientName }])
      : { clientName: this.data.msgClientName };
    db.collection('messages').where(condition)
      .orderBy('createdAt', 'desc').limit(20).get({
        success: function(res) {
          that.setData({ msgHistory: res.data.reverse() });
          wx.hideNavigationBarLoading();
          that.scrollMsgToBottom();
        },
        fail: function(err) {
          wx.hideNavigationBarLoading();
          console.error('拉取站内信历史失败：', err);
          wx.showModal({
            title: '记录加载失败',
            content: '请确认已在云开发控制台创建 messages 集合（权限：所有用户可读写）。',
            showCancel: false
          });
        }
      });
  },

  // 把 scroll-view 锚定到最后一条消息
  scrollMsgToBottom: function() {
    var list = this.data.msgHistory;
    if (list.length === 0) return;
    var that = this;
    // 等列表节点渲染完成后再设置锚点，否则 scroll-into-view 会落空
    setTimeout(function() {
      that.setData({ msgScrollInto: 'msg-' + list[list.length - 1]._id });
    }, 100);
  },

  onMsgInput: function(e) { this.setData({ msgInput: e.detail.value }); },

  submitClientMessage: function() {
    var that = this;
    var content = (this.data.msgInput || '').trim();
    if (!content) { wx.showToast({ title: '内容不能为空', icon: 'none' }); return; }

    var selectedMap = {};
    for (var s = 0; s < this.data.selectedMessageClientIds.length; s++) selectedMap[this.data.selectedMessageClientIds[s]] = true;
    var recipients = [];
    var missingOpenidCount = 0;
    for (var r = 0; r < this.data.messageRecipientList.length; r++) {
      var recipient = this.data.messageRecipientList[r];
      if (!selectedMap[recipient._id]) continue;
      if (!recipient.openid) {
        missingOpenidCount++;
        continue;
      }
      recipients.push(recipient);
    }
    if (this.data.selectedMessageClientIds.length === 0) {
      wx.showToast({ title: '请至少选择一名学员', icon: 'none' });
      return;
    }
    if (recipients.length === 0) {
      wx.showToast({ title: '所选学员缺少 OpenID', icon: 'none' });
      return;
    }

    var now = new Date();
    var pad = function(n) { return String(n).padStart(2, '0'); };
    var createdAt = now.getTime();
    var dateText = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate()) + ' ' + pad(now.getHours()) + ':' + pad(now.getMinutes());
    var targetOpenids = recipients.map(function(item) { return item.openid; });

    wx.showLoading({ title: '群发中...' });
    var tasks = targetOpenids.map(function(targetOpenid, index) {
      var recipient = recipients[index];
      return wx.cloud.callFunction({
        name: 'sendNotice',
        data: {
          type: 'stationMessage',
          targetOpenid: targetOpenid,
          noticeData: {
            clientName: recipient.name,
            from: that.data.coachProfile.nickname,
            content: content,
            createdAt: createdAt,
            dateText: dateText
          }
        }
      }).then(function(res) {
        return { ok: !!(res.result && res.result.ok), recipient: recipient };
      }).catch(function(err) {
        console.error('发送站内信失败：', recipient.name, err);
        return { ok: false, recipient: recipient };
      });
    });

    Promise.all(tasks).then(function(results) {
      wx.hideLoading();
      var successCount = results.filter(function(item) { return item.ok; }).length;
      var failCount = results.length - successCount + missingOpenidCount;
      if (successCount > 0) {
        that.setData({ msgInput: '' });
        that.fetchMsgHistory();
      }
      wx.showToast({
        title: failCount > 0 ? ('成功' + successCount + '人，失败' + failCount + '人') : ('已发送给' + successCount + '人'),
        icon: failCount > 0 ? 'none' : 'success'
      });
    }).catch(function(err) {
      wx.hideLoading();
      console.error('群发站内信失败：', err);
      wx.showModal({
        title: '发送失败',
        content: '请确认 sendNotice 云函数已重新上传部署。',
        showCancel: false
      });
    });
  },

  deleteMessage: function(e) {
    var that = this;
    var id = e.currentTarget.dataset.id;
    if (!id) return;
    wx.showModal({
      title: '删除消息',
      content: '是否删除该条消息？',
      confirmColor: '#FF5252',
      success: function(res) {
        if (!res.confirm) return;
        wx.showLoading({ title: '删除中...' });
        wx.cloud.database().collection('messages').doc(id).remove({
          success: function() {
            wx.hideLoading();
            wx.showToast({ title: '已删除', icon: 'success' });
            that.fetchMsgHistory();
          },
          fail: function(err) {
            wx.hideLoading();
            console.error('删除站内信失败：', err);
            wx.showToast({ title: '删除失败', icon: 'none' });
          }
        });
      }
    });
  },

