  onSearchInput: function(e) { this.setData({ searchQuery: e.detail.value }); this.processClientList(); },
  clearSearch: function() { this.setData({ searchQuery: '' }); this.processClientList(); },
  changeSortMode: function(e) { this.setData({ currentSortMode: e.currentTarget.dataset.mode }); this.processClientList(); },
  
  processClientList: function() {
    var list = JSON.parse(JSON.stringify(this.data.clientList)); var q = this.data.searchQuery;
    // 教练端统一展示：备注与昵称并存时显示「备注 (昵称)」，否则显示已有的一项。
    for (var d = 0; d < list.length; d++) {
      list[d].displayName = this.getClientDisplayName(list[d]);
    }
    if (q) { q = q.toLowerCase(); var temp = []; for (var i = 0; i < list.length; i++) { var hay = (list[i].name + '|' + (list[i].latestNickname || '') + '|' + (list[i].nickname || '') + '|' + (list[i].nickName || '') + '|' + (list[i].remark || '')).toLowerCase(); if (hay.indexOf(q) > -1) { temp.push(list[i]); } } list = temp; }
    var mode = this.data.currentSortMode;
    if (mode === 'classesAsc') { list.sort(function(a, b) { return a.leftClasses - b.leftClasses; }); } 
    else if (mode === 'classesDesc') { list.sort(function(a, b) { return b.leftClasses - a.leftClasses; }); } 
    else if (mode === 'daysAsc') { list.sort(function(a, b) { return a.daysLeft - b.daysLeft; }); } 
    else { list.sort(function(a, b) { return a.id - b.id; }); }
    this.setData({ filteredClientList: list });
  },
  
  generateDateStrip: function() {
    var dates = []; var weeks = ['周日', '周一', '周二', '周三', '周四', '周五', '周六']; var today = new Date();
    for (var i = 0; i < 7; i++) { var d = new Date(today.getTime() + i * 24 * 60 * 60 * 1000); var month = d.getMonth() + 1; var day = d.getDate(); var dateStr = month + '-' + day; dates.push({ date: dateStr, day: dateStr, week: i === 0 ? '今天' : weeks[d.getDay()] }); }
    this.setData({ dateList: dates, activeDate: dates[0].date });
  },

