  deleteCoachTag: function(e) {
    var that = this;
    var tag = e.currentTarget.dataset.tag;
    var tags = (this.data.coachProfile.coachTags || []).slice();
    if (!tag) return;
    if (tags.length <= 1) { wx.showToast({ title: '至少保留一个教练标签', icon: 'none' }); return; }
    wx.showModal({
      title: '删除标签',
      content: '是否删除该自定义标签？',
      confirmColor: '#FF5252',
      success: function(res) {
        if (!res.confirm) return;
        var newTags = [];
        for (var i = 0; i < tags.length; i++) {
          if (tags[i] !== tag) newTags.push(tags[i]);
        }
        var nextCoach = that.data.newCourseCoach === tag ? (newTags[0] || that.data.coachProfile.nickname) : that.data.newCourseCoach;
        that.setData({ 'coachProfile.coachTags': newTags, newCourseCoach: nextCoach });
        if (that.data.coachProfile._id) {
          wx.cloud.database().collection('coaches').doc(that.data.coachProfile._id).update({ data: { coachTags: newTags } });
        }
      }
    });
  },
  // ================= 🎯 复制上一日课表：把前一天的时段复制到当前日期，全部重置为待预约 =================
  copyTemplate: function() {
    var that = this;
    // 由 activeDate (如 "7-8") 推算前一天的日期字符串
    var parts = this.data.activeDate.split('-');
    var cur = new Date(new Date().getFullYear(), parseInt(parts[0]) - 1, parseInt(parts[1]));
    var prev = new Date(cur.getTime() - 24 * 3600000);
    var prevDate = (prev.getMonth() + 1) + '-' + prev.getDate();

    wx.showLoading({ title: '读取上一日课表...' });
    var db = wx.cloud.database();
    db.collection('schedules').where(this.buildCoachScopeCondition({ date: prevDate }, true)).get({
      success: function(res) {
        wx.hideLoading();
        var scopedSchedules = (res.data || []).filter(function(item) {
          return that.isRecordOwnedByCurrentCoach(item, true);
        });
        if (scopedSchedules.length === 0) {
          wx.showToast({ title: prevDate + ' 无课表可复制', icon: 'none' });
          return;
        }

        // 当前日期已占用的时间点直接跳过，避免复制出重复时段
        var existTimes = {};
        var all = that.data.allSchedules;
        for (var i = 0; i < all.length; i++) {
          if (all[i].date === that.data.activeDate) { existTimes[all[i].time] = true; }
        }
        var toCopy = [];
        for (var j = 0; j < scopedSchedules.length; j++) {
          if (!existTimes[scopedSchedules[j].time]) { toCopy.push(scopedSchedules[j]); }
        }
        if (toCopy.length === 0) {
          wx.showToast({ title: '时段均已存在，无需复制', icon: 'none' });
          return;
        }

        wx.showModal({
          title: '复制上一日课表',
          content: '将把 ' + prevDate + ' 的 ' + toCopy.length + ' 个时段复制到 ' + that.data.activeDate + '，并全部重置为「待预约」状态，是否继续？',
          confirmColor: '#F29100',
          success: function(mr) {
            if (!mr.confirm) return;
            wx.showLoading({ title: '批量复制中...', mask: true });
            var done = 0; var failed = 0;
            var finish = function() {
              if (done + failed < toCopy.length) return;
              wx.hideLoading();
              if (failed > 0) { wx.showToast({ title: '完成，' + failed + ' 条失败', icon: 'none' }); }
              else { wx.showToast({ title: '已复制 ' + done + ' 个时段', icon: 'success' }); }
              that.fetchSchedulesFromCloud();
            };
            for (var k = 0; k < toCopy.length; k++) {
              db.collection('schedules').add({
                data: {
                  date: that.data.activeDate, time: toCopy[k].time, type: toCopy[k].type || '1v1',
                  plan: '等待教练设定/核销', clientName: '待预约', leftClasses: '--',
                  status: 'open', statusText: '等待预约中',
                  coach: toCopy[k].coach || that.data.coachProfile.nickname,
                  coachId: that.data.coachProfile._id,
                  coachOpenid: that.data.currentCoachOpenid
                },
                success: function() { done++; finish(); },
                fail: function() { failed++; finish(); }
              });
            }
          }
        });
      },
      fail: function() {
        wx.hideLoading();
        wx.showToast({ title: '读取上一日课表失败', icon: 'none' });
      }
    });
  },
