  onCustomTagInput: function(e) { this.setData({ customTagInput: e.detail.value }); },
  // 自定义课程内容：加入标签池并自动选中
  addCustomTag: function() {
    var tag = (this.data.customTagInput || '').trim();
    if (!tag) { wx.showToast({ title: '请先输入课程内容', icon: 'none' }); return; }
    if (this.data.predefinedTags.indexOf(tag) > -1 || this.data.customTags.indexOf(tag) > -1) {
      wx.showToast({ title: '标签已存在，直接点选即可', icon: 'none' });
      this.setData({ customTagInput: '' });
      return;
    }
    var map = {};
    for (var key in this.data.selectedTagMap) { map[key] = true; }
    map[tag] = true;
    var newTags = this.data.customTags.concat(tag);
    this.setData({
      customTags: newTags,
      'coachProfile.customTrainingTags': newTags,
      selectedTags: this.data.selectedTags.concat(tag),
      selectedTagMap: map,
      customTagInput: ''
    });
    if (this.data.coachProfile._id) {
      wx.cloud.database().collection('coaches').doc(this.data.coachProfile._id).update({ data: { customTrainingTags: newTags } });
    }
  },
  deleteCustomTag: function(e) {
    var that = this;
    var tag = e.currentTarget.dataset.tag;
    var tags = (this.data.customTags || []).slice();
    if (!tag) return;
    wx.showModal({
      title: '删除标签',
      content: '是否删除该自定义标签？',
      confirmColor: '#FF5252',
      success: function(res) {
        if (!res.confirm) return;
        var newTags = [];
        for (var i = 0; i < tags.length; i++) {
          if (tags[i] !== tag) newTags.push(tags[i]);
        }
        var selected = that.data.selectedTags.slice();
        var idx = selected.indexOf(tag);
        if (idx > -1) selected.splice(idx, 1);
        var map = {};
        for (var key in that.data.selectedTagMap) {
          if (key !== tag) map[key] = true;
        }
        that.setData({
          customTags: newTags,
          'coachProfile.customTrainingTags': newTags,
          selectedTags: selected,
          selectedTagMap: map
        });
        if (that.data.coachProfile._id) {
          wx.cloud.database().collection('coaches').doc(that.data.coachProfile._id).update({ data: { customTrainingTags: newTags } });
        }
      }
    });
  },
